import React from 'react';
import { graphql, useStaticQuery } from 'gatsby';

export default function NowPanel() {
  const data = useStaticQuery(graphql`
    query NowPanelQuery {
      nowJson { updated items { label value } }
    }
  `);
  if (!data.nowJson) return null;
  return (
    <div className="panel">
      <div className="panel-title">/now</div>
      <div className="panel-sub">Updated {data.nowJson.updated}</div>
      <dl className="now-list">
        {data.nowJson.items.map((n, i) => (
          <div key={i} className="now-row">
            <dt>{n.label}</dt>
            <dd>{n.value}</dd>
          </div>
        ))}
      </dl>
    </div>
  );
}
